CREATE INDEX roles_by_project ON role_assignments(project_subject, assignment_id);
CREATE INDEX roles_by_workstream ON role_assignments(workstream_subject, assignment_id);
CREATE INDEX acknowledgements_by_assignment ON stand_down_acknowledgements(assignment_id, through_epoch, through_position DESC, acknowledgement_id DESC);
CREATE INDEX subscriptions_by_thread ON thread_subscriptions(thread_id, membership_id);
CREATE INDEX cooldown_human_posts ON record_identities(json_extract(payload, '$.record.placement.projectId'), json_extract(payload, '$.record.actor.humanId'), id) WHERE kind = 'post' AND json_extract(payload, '$.record.placement.kind') = 'project' AND json_extract(payload, '$.record.actor.kind') = 'human';
CREATE INDEX cooldown_session_posts ON record_identities(json_extract(payload, '$.record.placement.projectId'), json_extract(payload, '$.record.actor.session.endpoint.serviceId'), json_extract(payload, '$.record.actor.session.endpoint.endpointId'), json_extract(payload, '$.record.actor.session.sessionId'), id) WHERE kind = 'post' AND json_extract(payload, '$.record.placement.kind') = 'project' AND json_extract(payload, '$.record.actor.kind') = 'session';
CREATE INDEX human_role_operands ON record_identities(json_extract(payload, '$.record.holder.actor.identity.humanId'), json_extract(payload, '$.record.subject.kind'), json_extract(payload, '$.record.subject.subject'), id) WHERE kind = 'roleAssignment' AND json_extract(payload, '$.record.holder.actor.identity.kind') = 'human';
CREATE INDEX session_role_operands ON record_identities(json_extract(payload, '$.record.holder.actor.identity.session.endpoint.serviceId'), json_extract(payload, '$.record.holder.actor.identity.session.endpoint.endpointId'), json_extract(payload, '$.record.holder.actor.identity.session.sessionId'), json_extract(payload, '$.record.subject.kind'), json_extract(payload, '$.record.subject.subject'), id) WHERE kind = 'roleAssignment' AND json_extract(payload, '$.record.holder.actor.identity.kind') = 'session';
CREATE INDEX recent_project_lead ON record_identities(json_extract(payload, '$.record.subject.kind'), json_extract(payload, '$.record.subject.subject'), json_extract(payload, '$.record.role'), json_extract(payload, '$.record.envelope.position.position.position') DESC, id DESC) WHERE kind = 'roleAssignment';
CREATE INDEX current_plan_operand ON record_identities(json_extract(payload, '$.record.supersededBy'), json_extract(payload, '$.record.revision') DESC, id DESC) WHERE kind = 'planRevision';
CREATE INDEX guard_fact_operands ON record_identities(json_extract(payload, '$.record.kind.fact.subject.id'), json_extract(payload, '$.record.envelope.position.position.position') DESC, id DESC) WHERE kind = 'fact' AND json_extract(payload, '$.record.kind.kind') = 'evaluatorResult' AND json_extract(payload, '$.record.kind.fact.subject.kind') = 'project';
CREATE INDEX human_rejected_moves ON record_identities(json_extract(payload, '$.record.moveName'), json_extract(payload, '$.record.requester.actor.identity.humanId'), json_extract(payload, '$.record.outcome.kind'), id) WHERE kind = 'move' AND json_extract(payload, '$.record.requester.actor.identity.kind') = 'human';
CREATE INDEX session_rejected_moves ON record_identities(json_extract(payload, '$.record.moveName'), json_extract(payload, '$.record.requester.actor.identity.session.endpoint.serviceId'), json_extract(payload, '$.record.requester.actor.identity.session.endpoint.endpointId'), json_extract(payload, '$.record.requester.actor.identity.session.sessionId'), json_extract(payload, '$.record.outcome.kind'), id) WHERE kind = 'move' AND json_extract(payload, '$.record.requester.actor.identity.kind') = 'session';
